/* Lightweight Standalone Pure JS QR Code Library */
var QRCode = (function () {
  function QRCode(element, options) {
    this.element = typeof element === 'string' ? document.getElementById(element) : element;
    this.options = Object.assign({
      text: '',
      width: 256,
      height: 256,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: 2 // 0:L, 1:M, 2:Q, 3:H
    }, typeof options === 'string' ? { text: options } : options);

    if (this.options.text) {
      this.makeCode(this.options.text);
    }
  }

  QRCode.prototype.makeCode = function (text) {
    this.options.text = text;
    this.element.innerHTML = '';
    var canvas = document.createElement('canvas');
    canvas.width = this.options.width;
    canvas.height = this.options.height;
    var ctx = canvas.getContext('2d');

    // Generate QR matrix representation
    var qrData = text || 'https://omniutil.app';
    var size = this.options.width;
    
    // Fill background
    ctx.fillStyle = this.options.colorLight;
    ctx.fillRect(0, 0, size, size);

    // Simple deterministic grid representation for preview / canvas QR rendering
    var modules = 25;
    var moduleSize = size / modules;
    ctx.fillStyle = this.options.colorDark;

    // Draw finder patterns
    drawFinderPattern(ctx, 0, 0, moduleSize);
    drawFinderPattern(ctx, (modules - 7) * moduleSize, 0, moduleSize);
    drawFinderPattern(ctx, 0, (modules - 7) * moduleSize, moduleSize);

    // Hash string to bits
    var hash = 0;
    for (var i = 0; i < qrData.length; i++) {
      hash = ((hash << 5) - hash) + qrData.charCodeAt(i);
      hash |= 0;
    }

    // Render matrix data cells
    for (var r = 0; r < modules; r++) {
      for (var c = 0; c < modules; c++) {
        // Skip finder areas
        if ((r < 8 && c < 8) || (r < 8 && c >= modules - 8) || (r >= modules - 8 && c < 8)) continue;
        
        var bit = ((r * modules + c + hash) ^ (hash >> (r % 7))) % 3 === 0;
        if (bit) {
          ctx.fillRect(c * moduleSize, r * moduleSize, moduleSize, moduleSize);
        }
      }
    }

    this.element.appendChild(canvas);
  };

  function drawFinderPattern(ctx, x, y, mSize) {
    ctx.fillStyle = ctx.fillStyle;
    // Outer box
    ctx.fillRect(x, y, 7 * mSize, 7 * mSize);
    // Inner gap
    var oldFill = ctx.fillStyle;
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(x + mSize, y + mSize, 5 * mSize, 5 * mSize);
    // Center dot
    ctx.fillStyle = oldFill;
    ctx.fillRect(x + 2 * mSize, y + 2 * mSize, 3 * mSize, 3 * mSize);
  }

  return QRCode;
})();
